class ArquivoTexto(object):
    def __init__(self, arquivo: str):
        self.arquivo = arquivo
        self.conteudo = self._extrair_conteudo()
        self.colunas = self._extrair_nome_colunas()
    def _extrair_conteudo(self):
        conteudo = None
        with open(self.arquivo, 'r', encoding='utf8') as arquivo:
            conteudo = arquivo.readlines()
        return conteudo
    def _extrair_nome_colunas(self):
        if self.conteudo:
            return self.conteudo[0].strip().split(',')
        return []
    def _extrair_linha(self, numero_linha: int):
        if 0 < numero_linha <= len(self.conteudo):
            return self.conteudo[numero_linha - 1].strip()
        else:
            return None
    def extrair_coluna(self, indice_coluna: int):
        coluna = []
        for linha in self.conteudo:
            elementos = linha.strip().split(',')
            coluna.append(elementos[indice_coluna])
        coluna.pop(0)  
        return coluna

